/**
 * Session IDs are generated by the backend and only contain alphanumeric
 * characters, `-` or `_`. This pattern validates user-controlled values (for
 * example the `:id` route parameter) before they are interpolated into
 * database paths or API URLs, which blocks path traversal and injection via
 * crafted links.
 */
export const SessionIdPattern = /^[A-Za-z0-9_-]{1,128}$/;

// C0 control characters (0x00-0x1F) and DEL (0x7F) must not occur in
// single-line fields; multi-line fields additionally allow line feed (0x0A).
function hasControlChars(value: string, multiline: boolean): boolean {
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code === 0x7f || (code < 0x20 && !(multiline && code === 0x0a))) {
      return true;
    }
  }
  return false;
}

interface ValidateTextOptions {
  required?: boolean;
  maxLength: number;
  multiline?: boolean;
  requiredMessage?: string;
}

/**
 * Client-side hardening for free-text input: enforces a length limit and rejects control
 * characters, this only keeps obviously malicious or abusive input out of the request
 * payload.
 */
export function validateText(value: string, options: ValidateTextOptions): string | null {
  if (options.required && value.trim().length === 0) {
    return options.requiredMessage ?? 'This field is required';
  }
  if (value.length > options.maxLength) {
    return `Must be at most ${options.maxLength} characters`;
  }
  if (hasControlChars(value, options.multiline === true)) {
    return 'Contains invalid characters';
  }
  return null;
}
